#include <iostream>
#include <vector>
#include <queue>
#include <climits>
using namespace std;

// Dijkstra's Algorithm
vector<int> dijkstra(int source, vector<vector<pair<int,int>>>& adj, int V) {
    vector<int> dist(V, INT_MAX);
    priority_queue<pair<int,int>, vector<pair<int,int>>, greater<>> pq;

    dist[source] = 0;
    pq.push({0, source});

    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();

        if (d > dist[u]) continue; // Skip outdated entries

        for (auto [v, w] : adj[u]) {
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                pq.push({dist[v], v});
            }
        }
    }
    return dist;
}

int main() {
    int V = 5;
    vector<vector<pair<int,int>>> adj(V);
    // {neighbor, weight}
    adj[0].push_back({1, 4}); adj[0].push_back({2, 1});
    adj[1].push_back({3, 1});
    adj[2].push_back({1, 2}); adj[2].push_back({3, 5});
    adj[3].push_back({4, 3});

    vector<int> dist = dijkstra(0, adj, V);
    cout << "Shortest distances from vertex 0:" << endl;
    for (int i = 0; i < V; i++)
        cout << "To " << i << ": " << dist[i] << endl;
    return 0;
}

