import java.util.*;

public class Dijkstra {
    public static int[] dijkstra(int source, List<List<int[]>> adj, int V) {
        int[] dist = new int[V];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[source] = 0;

        // {distance, vertex}
        PriorityQueue<int[]> pq = new PriorityQueue<>((a,b) -> a[0]-b[0]);
        pq.offer(new int[]{0, source});

        while (!pq.isEmpty()) {
            int[] curr = pq.poll();
            int d = curr[0], u = curr[1];
            if (d > dist[u]) continue;

            for (int[] edge : adj.get(u)) {
                int v = edge[0], w = edge[1];
                if (dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    pq.offer(new int[]{dist[v], v});
                }
            }
        }
        return dist;
    }

    public static void main(String[] args) {
        int V = 5;
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < V; i++) adj.add(new ArrayList<>());
        adj.get(0).add(new int[]{1, 4});
        adj.get(0).add(new int[]{2, 1});
        adj.get(1).add(new int[]{3, 1});
        adj.get(2).add(new int[]{1, 2});
        adj.get(2).add(new int[]{3, 5});
        adj.get(3).add(new int[]{4, 3});

        int[] dist = dijkstra(0, adj, V);
        for (int i = 0; i < V; i++)
            System.out.println("To " + i + ": " + dist[i]);
    }
}

